# R1: Read list L
L = [71, 97, 54, 56, 44, 158, 45, 58, 82, 135, 113, 117, 86, 40, 12, 185, 63, 50, 111, 72, 90, 109, 61, 13, 92, 60, 91, 35, 114, 94, 105, 26, 15, 51, 102, 118, 76, 32, 108, 23, 22, 134, 83, 43, 64]

# R2: Generate candidate triples
triples = []
L_set = set(L)
n = len(L)
for i in range(n):
    a = L[i]
    for j in range(i+1, n):
        b = L[j]
        s = a + b
        if s in L_set and s != a and s != b:
            triples.append((a, b, s))

# R3: Build map from number to triples
num_to_triples = {num: [] for num in L}
for t in triples:
    a, b, c = t
    for num in t:
        num_to_triples[num].append(t)

# R4: Search for an exact cover of 15 triples
target = len(L) // 3  # 15
solution = None
selected = []
used = set()

def backtrack():
    global solution
    if solution is not None:
        return
    if len(selected) == target:
        if used == set(L):
            solution = list(selected)
        return
    # Choose an unused number with fewest candidate triples
    min_n = None
    min_choices = None
    for n in L:
        if n not in used:
            candidates = [t for t in num_to_triples[n] if all(x not in used for x in t)]
            c = len(candidates)
            if c == 0:
                return
            if min_choices is None or c < min_choices:
                min_choices = c
                min_n = n
                if min_choices == 1:
                    break
    for t in num_to_triples[min_n]:
        if all(x not in used for x in t):
            selected.append(t)
            for x in t:
                used.add(x)
            backtrack()
            if solution is not None:
                return
            selected.pop()
            for x in t:
                used.remove(x)

backtrack()

# R5: Output result
if solution:
    print("Solution found:")
    for a, b, c in solution:
        print(f"({a}, {b}, {c})")
else:
    print("No solution exists.")

# WITNESS
import json
if solution:
    witness = {
        "polarity": "positive",
        "data": {
            "triples": solution
        }
    }
else:
    witness = {
        "polarity": "negative",
        "argument": "No exact cover of triples exists for the given list."
    }
print("WITNESS:", json.dumps(witness))
